"""Judges' Q&A sheet → HTML (printed to PDF by Chrome). Run from the repo root: python3 submissions/phase2/demo-script/qa.py <out.html>"""
import html, sys
QA = [
("Phase 2: today's test pack", "K", "Which step from your deck handles each of the six cases?", "The Verifier, which is code and not AI, handles five: Not found, Mismatch, Needs fix, Retracted and Duplicate. It compares the pasted reference with Crossref and OpenAlex field by field. Case six, no source exists, is the Planner, Scout and Verifier together: only a registry record can become a source, so there is nothing to invent with.", "X-ray → the eight references"),
("Phase 2: today's test pack", "K", "Did you hard-code the eight references?", "No. They are general rules: we split lists by format, compare each field with the registry record, and call two lines duplicates when they resolve to the same record. Our tests use other references, and you can paste any reference now.", "X-ray → paste a judge's own reference"),
("Phase 2: today's test pack", "K", "What happens when I reject a fix?", "The reference stays exactly as typed, marked Needs fix, in the library and in every export. Nothing is corrected, deleted or swapped without a click.", "X-ray → Reject fix → My reference list"),
("Phase 2: today's test pack", "K", "How do you know two references are the same paper?", "Both resolve to the same registry record, the same DOI, whatever format they were typed in. We offer Merge and keep one entry; the list can never hold the same record twice.", "X-ray → reference G → Merge"),
("Phase 2: today's test pack", "K", "How does it decide that no source exists?", "It reads the specific things the question names, here the AI Club Hackathon 2026 and SP Jain Dubai. If no source returned by three registries mentions them, the answer is Not found. The related papers shown are real, checked and labelled as related, not as an answer.", "Research → request 1"),
("Phase 2: today's test pack", "Z", "Do the warnings really travel into the export?", "Yes. Export the list and each non-verified item carries its mark in the file: Retracted, Needs fix, Mismatch, Not found or web source. The same note is written into BibTeX, RIS and CSL-JSON.", "Library → Export → open the file"),
("Phase 2: today's test pack", "Z", "What if someone hides an instruction in a note or a source?", "It is treated as content. Our injection shield flags it, stores it as text and follows nothing. A status can only change when a check runs.", "Research → request 3"),
("Phase 2: today's test pack", "K", "Why does your label say Partial and not “Not checked”?", "Partial is our name for not fully checked: a web page no scholarly database lists, a DOI given with nothing to compare, or a registry that did not answer. The legend on the page says so.", None),
("Top 5: most likely", "K", "What does “Verified” actually mean?", "For a reference: the title, first author and year match a record in two public registries, Crossref and OpenAlex, and it isn’t retracted. For a claim: its quote is word for word in the source, and the Skeptic found no problem. It doesn’t mean the paper is right.", "X-ray → “How this was decided” on a Verified row"),
("Top 5: most likely", "K", "Every team built a citation checker. What’s different about yours?", "Three things. A real DOI on the wrong paper passes a DOI checker and fails ours: on the same 51 references a DOI-only check let twelve fakes and retracted papers through; we let none. We measured it and publish it. And it all still works with the AI off.", "Trust Center → “Why a DOI check is not enough”"),
("Top 5: most likely", "K", "How do you stop the AI inventing references?", "It can’t output one. Its answer format only accepts IDs of records we fetched from the registries. An invented ID is blocked by code and logged. Prompts aren’t the guardrail; code is.", None),
("Top 5: most likely", "Z", "How did you test it?", "Fifty-one test references we built: 30 real, 11 fakes, 5 retracted, 5 web pages. Eleven of eleven fakes caught, zero fakes marked Verified, 30 of 30 real verified, 5 of 5 retractions. Today we also ran your pack and fourteen unseen references in six formats. It’s a small set we made, and we say so.", "Trust Center → results card"),
("Top 5: most likely", "Z", "Who is accountable if a citation is wrong?", "The student is the author: they approve the plan, the sources and every claim. We’re accountable for our checks: they’re plain code with published results. Faculty can re-check any list from its certificate.", None),
("How it works", "K", "Is this RAG?", "Yes, a strict kind. The AI writes only from records we fetched from public registries, and code checks every quote against the source. We don’t use a vector database: the registries are the retrieval layer.", None),
("How it works", "K", "Which AI models do you use, and why?", "Free open-weight models on Groq: gpt-oss for planning, reading and drafting, and Qwen, from a different company, as the Skeptic, so it doesn’t share the writer’s blind spots. Checking a reference uses zero AI calls.", None),
("How it works", "K", "What if the AI or a database goes down?", "A fallback model first, then Rules mode, which still verifies every reference. If a registry doesn’t answer, the row says “could not be checked, try again”. It never says Verified when no check ran.", "AI autonomy → Off"),
("How it works", "K", "What if Crossref and OpenAlex disagree?", "Then it isn’t Verified. It says Needs fix or Partial, and shows what you typed next to what each registry says.", None),
("How it works", "K", "Can it read paywalled papers?", "No, and it says so. Quotes are checked against abstracts only. A quote it cannot find is never confirmed: it says not found, or that the full text was not available.", "Research → request 2"),
("How it works", "K", "A real paper with no DOI: is it called fake?", "No. We search by title and authors. Today’s Vaswani reference has no DOI and comes out Verified.", "X-ray → reference F"),
("How it works", "K", "What about a web page with no author or date?", "It is a web source: the organisation is the author, the date is n.d., and it is labelled as not checked in a scholarly database. It can never be Verified.", "X-ray → reference H"),
("Ethics and governance", "Z", "Where does student data go?", "Nowhere we store it. No accounts; the library lives in your browser. Code removes emails, phone numbers and IDs before anything reaches the AI. A certificate carries its data inside its own link.", None),
("Ethics and governance", "Z", "Why is there no sign-in?", "On purpose: no student data sits on our server. As a product we would add optional accounts for sync across devices.", None),
("Ethics and governance", "Z", "How is AI use disclosed?", "Three ways: every AI sentence is labelled, an AI-use statement is written from the session log, and the prompt ledger and certificate let faculty see it. It never writes “I wrote this myself”; the student types that.", None),
("Ethics and governance", "Z", "Doesn’t this make students lazier?", "It’s built for the opposite: three approvals, an AI dial that goes to Off, read-before-you-cite warnings, and the student writes every word.", None),
("Ethics and governance", "Z", "Why not detect AI-written essays instead?", "Detectors falsely accuse people: a Stanford study found they flagged 61% of essays by non-native English writers. We check sources, not people.", None),
("Limits and honesty", "K", "What’s the weakest part?", "Web pages: three of five in our tests, so they’re capped at Partial. A title typed on its own, with no author or year, can match a similar title, so it stays Partial. And claims rely on abstracts. We publish all of it.", None),
("Limits and honesty", "K", "Why did one AI run verify everything and another flag everything?", "The AI varies between runs. The labels don’t depend on its opinion: code checks the quote, and the Skeptic can only lower a label, never raise one.", None),
("Limits and honesty", "K", "Did you use AI to build this?", "Yes, AI coding tools, under our direction. Every prompt is in our prompt log, including the ones that failed today. The honesty decisions are ours.", None),
("Product and impact", "A", "Why would a student switch from Zotero?", "They don’t have to. Import your Zotero file, keep only the references that are real, and export back to Zotero or Mendeley, with each status attached.", "Library → Import"),
("Product and impact", "A", "Why 3D? Isn’t it decoration?", "The 3D is the idea: a UV lamp shows what’s real. Every check also has a plain table, and Plain view turns the 3D off.", None),
("Product and impact", "A", "How would SP Jain roll this out?", "It’s free, there are no accounts, and it works in a browser, even on a phone. Faculty accept the QR certificate with a submission. We could pilot it with one cohort in a week.", None),
("Product and impact", "A", "What would you build next?", "Full-text checking where papers are open access, a shared library for group projects, optional accounts for sync, and a faculty view. Each reuses the same checks.", None),
]
WHO = {"K": ("Krishna", "#1F6F68"), "Z": ("Zedan", "#5B4BC4"), "A": ("Avighna", "#B8329A")}
e = lambda x: html.escape(x, quote=False)
css = '''@page{size:A4;margin:12mm 13mm}@font-face{font-family:"ArchivoX";src:local("Archivo Expanded ExtraBold")}@font-face{font-family:"ArchivoS";src:local("Archivo SemiBold")}
body{font:9.6pt/1.42 "Archivo","Helvetica Neue",Arial,sans-serif;color:#0E2A23;margin:0}h1{font:800 22pt "ArchivoX","Archivo",sans-serif;margin:0 0 2mm}
h2{font:600 12pt "ArchivoS","Archivo",sans-serif;margin:5mm 0 2mm;border-bottom:.6pt solid #C9D5CD;padding-bottom:1mm;break-after:avoid}
.eb{font:7.5pt "Martian Mono",Menlo,monospace;letter-spacing:.14em;text-transform:uppercase;color:#5B4BC4;margin-bottom:2mm}
.box{background:#F7FAF7;border:.6pt solid #C9D5CD;border-radius:3mm;padding:3mm 4mm;margin:2mm 0 3mm;font-size:9pt}
.q{break-inside:avoid;margin:0 0 3mm}.qt{font-weight:600}.who{display:inline-block;font:600 7pt "Martian Mono",monospace;color:#fff;border-radius:99px;padding:.6mm 2mm;margin-right:2mm;vertical-align:1px}
.a{font-family:"Literata",Georgia,serif;font-size:9.8pt;margin:.8mm 0 0}.show{font:7.8pt "Martian Mono",monospace;color:#1F6F68;margin-top:.6mm}'''
out = [f'<!doctype html><meta charset="utf-8"><title>Team 7 judge Q&A</title><style>{css}</style>',
 '<div class="eb">Team 7 · Veracite · 2 minutes of questions · 26 Nov 2026 · updated after Phase 2</div><h1>JUDGES’ QUESTIONS: WHAT TO SAY</h1>',
 '<div class="box"><b>How to use this.</b> About three or four questions in two minutes, so <b>20 seconds per answer</b>. The person named answers first; if someone else built it, hand over in one sentence. Give a number or a click wherever you can. If you don’t know: “We haven’t measured that yet. What we have measured is…” <b>Learn the Phase 2 section and the top five first.</b> Labels on screen today: Verified · Needs fix · Mismatch (a chimera) · Retracted · Not found · Partial (not fully checked).</div>']
sec = None
for s_, w, q, a, show in QA:
    if s_ != sec:
        sec = s_; out.append(f"<h2>{e(sec)}</h2>")
    n, c = WHO[w]
    out.append(f'<div class="q"><div><span class="who" style="background:{c}">{n.upper()}</span><span class="qt">{e(q)}</span></div><div class="a">{e(a)}</div>' + (f'<div class="show">Show: {e(show)}</div>' if show else "") + "</div>")
open(sys.argv[1], "w").write("\n".join(out)); print(len(QA), "questions")
